import requests

response = requests.get(
    "https://api.notify-me.app/v1/pre-order-notifications/",
    headers={"X-Api-Key": "YOUR_API_KEY"}
)
print(response.json())

fetch("https://api.notify-me.app/v1/pre-order-notifications/", {
    method: "GET",
    headers: {
        "X-Api-Key": "YOUR_API_KEY"
    }
})
.then(response => response.json())
.then(data => console.log(data));

package main

import (
    "encoding/json"
    "fmt"
    "net/http"
)

func main() {
    req, _ := http.NewRequest("GET", "https://api.notify-me.app/v1/pre-order-notifications/", nil)
    req.Header.Set("X-Api-Key", "YOUR_API_KEY")

    client := &http.Client{}
    resp, _ := client.Do(req)
    defer resp.Body.Close()

    var result map[string]interface{}
    json.NewDecoder(resp.Body).Decode(&result)
    fmt.Println(result)
}

const axios = require("axios");

axios({
    method: "get",
    url: "https://api.notify-me.app/v1/pre-order-notifications/",
    headers: {
        "X-Api-Key": "YOUR_API_KEY"
    }
})
.then(response => console.log(response.data))
.catch(error => console.error(error));

